CREATE OR REPLACE FUNCTION public.normalize_behaviour_incident() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF lower(trim(NEW.category)) = ANY (ARRAY['excellent participation','homework excellence','leadership','helping a peer','merit']) THEN NEW.is_positive := true; ELSIF lower(trim(NEW.category)) = ANY (ARRAY['disruption in class','incomplete work','late arrival','uniform violation','concern']) THEN NEW.is_positive := false; END IF; NEW.points := CASE WHEN NEW.is_positive THEN greatest(abs(NEW.points), 5) ELSE -greatest(abs(NEW.points), 5) END; IF NEW.note LIKE 'Recognised for % during class.' OR NEW.note LIKE 'Logged incident: %. Teacher followed up.' THEN NEW.note := CASE WHEN NEW.is_positive THEN 'Recognised for ' || lower(NEW.category) || ' during class.' ELSE 'Logged incident: ' || lower(NEW.category) || '. Teacher followed up.' END; END IF; RETURN NEW; END; $$; CREATE TRIGGER normalize_behaviour_incident_before_write BEFORE INSERT OR UPDATE ON public.behaviour_notes FOR EACH ROW EXECUTE FUNCTION public.normalize_behaviour_incident();